mapper.select:
SELECT current_group.group_jid AS groupJid, COALESCE(participant.pn_jid, participant.lid_jid) AS participantJid, participant.phone, participant.last_joined_at AS joinedAt FROM wa_group current_group INNER JOIN wa_group_participant participant ON participant.tenant_id = current_group.tenant_id AND participant.group_id = current_group.id AND participant.last_joined_at IS NOT NULL WHERE current_group.tenant_id = #{tenantId} AND current_group.group_jid IN
#{groupJid}
ORDER BY current_group.group_jid ASC, participant.last_joined_at ASC, COALESCE(participant.pn_jid, participant.lid_jid) ASC
